const e="Przepuklina krążka",n="Wyrośla kostne",i="Zamrożony bark",a="Choroba zwyrodnieniowa kolana",r="Łąkotka",o="Haluks",t="Kręg szyjny",s="Kość biodrowa",c="Ścięgna",d="Cieśń nadgarstka",z="Zapalenie rozcięgna podeszwowego",l="Ostroga piętowa",u="Choroba zwyrodnieniowa stawu kciuka",h="Staw siodełkowaty",k="Zwężenie",w="Sklepienie barku",m="Stenoza kanału kręgowego",b="Wyrostek kostny",g="Mięśnie prostowniki",p="Łokieć tenisisty",y="Zastrzyk z kortyzonu",j="Akupunktura",f="Żel przeciwbólowy",S="Operacja",B="Orteza kciuka",K="Zastrzyk z kwasu hialuronowego",D="Zespół cieśni nadgarstka",P="Terapia ruchem",M="Leżenie w łóżku",v="Bóle karku",W="Ból pięty",G="Ból ścięgna Achillesa",A="Podpiętek",C="Paluch koślawy",N="Wkładki",T="Szyna na noc",Z="Gonartroza",F="Artroskopia",H="Koksartroza",E="Tabletki przeciwbólowe",R={"Übungsblatt zusammenstellen":"Zestawienie arkusza ćwiczeń",Übungsblatt:"Arkusz ćwiczeń","Welche Übungen sollen aufs Blatt? Die Reihenfolge folgt der Auswahl.":"Które ćwiczenia umieścić na arkuszu? Kolejność wynika z wyboru.","z. B. Jeden Morgen vor dem Aufstehen, Kontrolle in sechs Wochen":"np. Codziennie rano przed wstaniem z łóżka, kontrola za sześć tygodni","Im Druckdialog „Hintergrundgrafiken“ einschalten, sonst fehlen die Bilder.":"W oknie drukowania proszę włączyć „Grafika tła”, w przeciwnym razie zabraknie obrazów.","Ihre Übungen für zu Hause":"Ćwiczenia do wykonywania w domu","Regelmäßig ist wichtiger als viel. Leichtes Ziehen oder Anstrengung ist in Ordnung – stechender oder zunehmender Schmerz nicht. Dann die Übung kleiner machen oder weglassen und uns Bescheid geben.":"Regularność jest ważniejsza niż ilość. Lekkie ciągnięcie lub wysiłek są w porządku – ostry lub narastający ból już nie. Wtedy należy zmniejszyć zakres ćwiczenia lub je pominąć i dać nam znać.","Links Übungen auswählen.":"Ćwiczenia proszę wybrać po lewej stronie.","Die Übungen ersetzen keine Krankengymnastik, wenn diese verordnet ist. Werden die Beschwerden stärker, kommen Taubheit oder Lähmungen dazu, melden Sie sich bitte bei uns.":"Ćwiczenia nie zastępują fizjoterapii, jeśli została zalecona. Jeśli dolegliwości się nasilają lub pojawia się drętwienie albo porażenie, proszę się z nami skontaktować.","Sehne schlank und glatt":"Ścięgno smukłe i gładkie","Achillessehne gereizt":"Ścięgno Achillesa podrażnione","verdickt, 2–6 cm über der Ferse":"pogrubiałe, 2–6 cm nad piętą","Kern liegt mittig":"Jądro leży pośrodku",Bandscheibenvorfall:e,"Kern drückt auf den Nerv":"Jądro uciska nerw","Schmerz ins Bein":"Ból promieniuje do nogi","translate(3 -9)":"translate(3 -9)","Knorpel polstert Kopf und Pfanne":"Chrząstka amortyzuje głowę i panewkę",Hüftarthrose:"Choroba zwyrodnieniowa biodra","Knorpel weg, Spalt eng":"Brak chrząstki, wąska szpara","Pfannendach verdichtet":"Sklepienie panewki zagęszczone",Hüftkopf:"Głowa kości udowej",Knochenzacken:n,"M-72 -20 C-80 10 -72 42 -54 64 C-38 96 -32 150 -30 250 L16 250 C18 150 24 100 42 70 C66 50 80 14 72 -20 A75 75 0 0 0 -72 -20 Z":"M-72 -20 C-80 10 -72 42 -54 64 C-38 96 -32 150 -30 250 L16 250 C18 150 24 100 42 70 C66 50 80 14 72 -20 A75 75 0 0 0 -72 -20 Z","Weite Kapsel, Arm frei":"Szeroka torebka, ramię swobodne",Schultersteife:i,"Kapsel geschrumpft":"Torebka obkurczona","Kapsel entzündet":"Torebka zapalnie zmieniona","Pfeil: so weit lässt sich der Arm heben":"Strzałka: tak wysoko można unieść ramię","rotate(5 150 330) translate(0 -6)":"rotate(5 150 330) translate(0 -6)","Spalt innen und außen gleich":"Szpara po obu stronach jednakowa",Kniearthrose:a,"Innen eng, O-Bein":"Wąska od środka, kolano szpotawe",Meniskus:r,"Großzehe steht gerade":"Paluch prosty","Hallux valgus":"Paluch koślawy","Großzehe knickt nach außen":"Paluch odchyla się na zewnątrz",Ballen:o,"translate(150 140)":"translate(150 140)","translate(96 196) rotate(-28)":"translate(96 196) rotate(-28)","Kopf über den Schultern":"Głowa nad barkami","HWS-Syndrom":"Zespół szyjny","Kopf weit vorgeschoben":"Głowa mocno wysunięta do przodu",Halswirbel:t,"Muskeln unter Zug":"Mięśnie napięte",Darmbein:s,"Gelenk gereizt":"Staw podrażniony","Schmerz im Gesäß":"Ból w pośladku","strahlt in den Oberschenkel":"promieniuje do uda",Sehnen:c,"Viel Platz im Tunnel":"Dużo miejsca w kanale","Nerv gequetscht":"Nerw uciśnięty",Karpaltunnel:d,"Eng, Finger kribbeln":"Ciasno, mrowienie palców","Sehnenplatte spannt das Gewölbe":"Rozcięgno napina łuk stopy",Plantarfasziitis:z,"Ansatz an der Ferse gereizt":"Przyczep na pięcie podrażniony","Zug bei jedem Schritt":"Ciągnięcie przy każdym kroku",Fersensporn:l,"M-27 -6 C-30 -24 -22 -44 -20 -64 L-18 -140 C-26 -150 -26 -170 -10 -176 L10 -176 C26 -170 26 -150 18 -140 L20 -64 C22 -44 30 -24 27 -6 C12 -16 -12 -16 -27 -6 Z":"M-27 -6 C-30 -24 -22 -44 -20 -64 L-18 -140 C-26 -150 -26 -170 -10 -176 L10 -176 C26 -170 26 -150 18 -140 L20 -64 C22 -44 30 -24 27 -6 C12 -16 -12 -16 -27 -6 Z","M-18 -186 C-22 -194 -18 -200 -14 -204 L-11 -266 C-18 -272 -18 -286 -6 -288 L6 -288 C18 -286 18 -272 11 -266 L14 -204 C18 -200 22 -194 18 -186 C8 -190 -8 -190 -18 -186 Z":"M-18 -186 C-22 -194 -18 -200 -14 -204 L-11 -266 C-18 -272 -18 -286 -6 -288 L6 -288 C18 -286 18 -272 11 -266 L14 -204 C18 -200 22 -194 18 -186 C8 -190 -8 -190 -18 -186 Z","M-14 -296 C-14 -304 -10 -308 -9 -312 L-9 -332 C-12 -340 -6 -352 0 -352 C6 -352 12 -340 9 -332 L9 -312 C10 -308 14 -304 14 -296 C6 -299 -6 -299 -14 -296 Z":"M-14 -296 C-14 -304 -10 -308 -9 -312 L-9 -332 C-12 -340 -6 -352 0 -352 C6 -352 12 -340 9 -332 L9 -312 C10 -308 14 -304 14 -296 C6 -299 -6 -299 -14 -296 Z","M-32 6 C-14 -4 14 -4 32 6 C46 16 50 36 40 48 C20 58 -20 58 -40 46 C-50 34 -46 16 -32 6 Z":"M-32 6 C-14 -4 14 -4 32 6 C46 16 50 36 40 48 C20 58 -20 58 -40 46 C-50 34 -46 16 -32 6 Z","M-27 -6 C-12 -16 12 -16 27 -6 L32 6 C14 -4 -14 -4 -32 6 Z":"M-27 -6 C-12 -16 12 -16 27 -6 L32 6 C14 -4 -14 -4 -32 6 Z","translate(-17 7) rotate(-8)":"translate(-17 7) rotate(-8)","Daumen gleitet glatt":"Kciuk porusza się gładko",Rhizarthrose:u,"Daumenansatz schmerzt":"Ból u nasady kciuka",Sattelgelenk:h,"Knorpel glatt":"Chrząstka gładka","Zacken, Daumen verschoben":"Wyrośla, kciuk przesunięty","Sehne gleitet frei":"Ścięgno przesuwa się swobodnie",Engpass:k,"Beim Armheben wird es eng":"Przy unoszeniu ręki robi się ciasno",Schulterdach:w,"Sehne eingerissen":"Ścięgno naderwane","Weiter Kanal für die Nerven":"Szeroki kanał dla nerwów",Wirbelkörper:"Trzon kręgu",Spinalkanalstenose:m,"Kanal eingeengt":"Kanał zwężony","Gelenke verdickt":"Stawy pogrubiałe","Bänder verdickt":"Więzadła pogrubiałe",Knochenvorsprung:b,Streckmuskeln:g,"Sehne sitzt fest und ruhig am Knochen":"Ścięgno mocno i spokojnie przytwierdzone do kości","Sehnenansatz gereizt":"Przyczep ścięgna podrażniony",Tennisellenbogen:p,"Schmerz beim Greifen und Heben":"Ból przy chwytaniu i podnoszeniu","Schulterschmerz beim Armheben":"Ból barku przy unoszeniu ręki","Impingement, Rotatorenmanschette":"Konflikt podbarkowy, stożek rotatorów","Der Schmerz sitzt außen an der Schulter und zieht oft in den Oberarm.":"Ból zlokalizowany jest po zewnętrznej stronie barku i często promieniuje do ramienia.","Typisch ist er, wenn Sie den Arm seitlich anheben oder über Kopf arbeiten. Dazwischen gibt es oft einen besonders schmerzhaften Bereich.":"Jest typowy przy unoszeniu ręki w bok lub przy pracy nad głową. Pomiędzy tymi pozycjami często występuje szczególnie bolesny zakres ruchu.","Viele können nachts nicht auf der kranken Seite liegen.":"Wiele osób nie może w nocy leżeć na chorej stronie.","Die Schulter lässt sich aber meist noch gut bewegen, wenn jemand anders den Arm führt.":"Bark zwykle jednak nadal dobrze się porusza, gdy ramię prowadzi ktoś inny.","Die leuchtende Sehne zieht oben über den Oberarmkopf, direkt unter dem knöchernen Schulterdach.":"Podświetlone ścięgno biegnie nad głową kości ramiennej, tuż pod kostnym sklepieniem barku.","Zwischen Sehne und Schulterdach liegt ein Schleimbeutel, der wie ein Gleitkissen wirkt.":"Pomiędzy ścięgnem a sklepieniem barku leży kaletka maziowa, która działa jak poduszka ślizgowa.","Sind Sehne oder Schleimbeutel gereizt, wird es dort beim Armheben eng und schmerzhaft.":"Gdy ścięgno lub kaletka są podrażnione, przy unoszeniu ręki robi się tam ciasno i bolesnie.","Die Sehnen der Schulter tragen viel Last und werden mit dem Alter weniger belastbar.":"Ścięgna barku przenoszą duże obciążenia, a z wiekiem stają się mniej wytrzymałe.","Häufige Arbeit über Kopf oder ein plötzliches Mehr an Training kann sie überlasten.":"Częsta praca nad głową lub nagłe zwiększenie treningu mogą je przeciążyć.","Manchmal lagert sich Kalk in der Sehne ab. Das kann sehr heftig wehtun, löst sich aber oft von selbst wieder auf.":"Czasami w ścięgnie odkłada się wapń. Może to bardzo boleć, ale często ustępuje samoistnie.","Kleine Risse in der Sehne haben ab 50 Jahren viele Menschen ohne Beschwerden. Ein Bild allein erklärt den Schmerz deshalb nicht.":"Małe pęknięcia ścięgna ma po 50. roku życia wiele osób bez żadnych dolegliwości. Dlatego sam obraz nie tłumaczy bólu.","Mit gezielten Übungen bessert sich der Schmerz bei den meisten innerhalb von drei bis sechs Monaten deutlich.":"Dzięki celowanym ćwiczeniom ból u większości osób wyraźnie się zmniejsza w ciągu trzech do sześciu miesięcy.","Gezielte Übungen":"Celowane ćwiczenia","Kräftigungsübungen für Schulter und Schulterblatt, zu Hause oder mit Krankengymnastik, sind die wichtigste Behandlung.":"Ćwiczenia wzmacniające bark i łopatkę, w domu lub z fizjoterapią, są najważniejszą metodą leczenia.","Schmerzmittel für kurze Zeit":"Leki przeciwbólowe przez krótki czas","Ibuprofen oder ähnliche Mittel für einige Tage lindern den Schmerz, damit Sie üben und schlafen können.":"Ibuprofen lub podobne leki przez kilka dni łagodzą ból, aby można było ćwiczyć i spać.",Kortisonspritze:y,"Eine Spritze unter das Schulterdach lindert den Schmerz für einige Wochen, heilt die Sehne aber nicht.":"Zastrzyk pod sklepienie barku łagodzi ból na kilka tygodni, ale nie leczy ścięgna.","Stoßwellen bei Kalkschulter":"Fale uderzeniowe przy barku wapniejącym","Bei Kalk in der Sehne können Stoßwellen den Schmerz lindern; meist müssen Sie sie selbst bezahlen.":"Przy wapniu w ścięgnie fale uderzeniowe mogą złagodzić ból; zwykle trzeba za nie zapłacić samodzielnie.",Akupunktur:j,"Einzelne Studien zeigen einen kleinen Nutzen, die Ergebnisse sind aber uneinheitlich.":"Pojedyncze badania wykazują niewielką korzyść, ale wyniki są niejednolite.","OP zur Erweiterung":"Operacja poszerzająca","Das Abtragen von Knochen am Schulterdach hilft in Studien nicht besser als eine Schein-OP oder Übungen.":"Usunięcie kości przy sklepieniu barku w badaniach nie pomaga lepiej niż pozorowana operacja lub ćwiczenia.","Arbeiten Sie möglichst unterhalb der Schulterhöhe und holen Sie Dinge mit einer Leiter statt mit gestrecktem Arm.":"Proszę pracować możliwie poniżej wysokości barku i sięgać po przedmioty z drabiny, a nie z wyprostowaną ręką.","Ganz schonen sollten Sie die Schulter nicht: Bewegung im schmerzarmen Bereich ist ausdrücklich erlaubt.":"Nie należy całkiem oszczędzać barku: ruch w zakresie mało bolesnym jest wyraźnie dozwolony.","Können Sie nach einem Sturz oder Ruck den Arm plötzlich nicht mehr heben, kommen Sie bitte innerhalb weniger Tage – ein frischer Sehnenriss wird früh besser versorgt. Bei Fieber mit roter, heißer Schulter sofort.":"Jeśli po upadku lub szarpnięciu nagle nie można już unieść ręki, proszę zgłosić się w ciągu kilku dni – świeże zerwanie ścięgna leczy się lepiej wcześnie. Przy gorączce z czerwonym, gorącym barkiem – natychmiast.","Frozen Shoulder, Schultersteife":"Frozen shoulder, zamrożony bark","Die Schulter wird ohne erkennbaren Grund schmerzhaft und dann zunehmend steif.":"Bark staje się bolesny bez widocznej przyczyny, a potem coraz bardziej sztywny.","Anfangs stehen starke Schmerzen im Vordergrund, auch nachts in Ruhe.":"Na początku dominuje silny ból, także w nocy w spoczynku.","Später lässt der Schmerz nach, aber der Arm lässt sich kaum noch nach außen drehen oder anheben – auch nicht, wenn jemand anders hilft.":"Później ból słabnie, ale ramienia prawie nie można już odwieść na zewnątrz ani unieść – także gdy pomaga ktoś inny.","Am Ende taut die Schulter langsam wieder auf und wird wieder beweglicher.":"Na końcu bark powoli „rozmarza” i znów staje się ruchomy.","Die leuchtende Hülle ist die Gelenkkapsel. Sie umschließt den Oberarmkopf wie ein weiter Sack.":"Podświetlona osłonka to torebka stawowa. Otacza głowę kości ramiennej jak szeroki worek.","Bei der Schultersteife entzündet sich die Kapsel, verdickt und schrumpft.":"W zamrożonym barku torebka ulega zapaleniu, pogrubia się i obkurcza.","Dadurch wird das Gelenk eng, und jede Bewegung bis an die Grenze tut weh.":"Przez to staw robi się ciasny, a każdy ruch do granicy zakresu boli.","Warum sich die Kapsel entzündet, ist meist unklar.":"Dlaczego torebka ulega zapaleniu, zwykle nie wiadomo.","Am häufigsten trifft es Menschen zwischen 40 und 60 Jahren, Frauen etwas öfter.":"Najczęściej dotyka osób w wieku od 40 do 60 lat, kobiety nieco częściej.","Diabetes und Schilddrüsenerkrankungen erhöhen das Risiko deutlich.":"Cukrzyca i choroby tarczycy wyraźnie zwiększają ryzyko.","Manchmal beginnt es nach einer Verletzung oder wenn die Schulter längere Zeit ruhiggestellt war.":"Czasem zaczyna się po urazie lub gdy bark był przez dłuższy czas unieruchomiony.","Die Schultersteife heilt fast immer von selbst aus, braucht aber Geduld: meist ein bis zwei, manchmal drei Jahre.":"Zamrożony bark prawie zawsze goi się samoistnie, ale wymaga cierpliwości: zwykle od roku do dwóch lat, czasem trzech.","Kortisonspritze ins Gelenk":"Zastrzyk z kortyzonu do stawu","Früh gegeben lindert sie den Schmerz über Wochen bis wenige Monate und erleichtert die Bewegung.":"Podany wcześnie łagodzi ból na kilka tygodni do kilku miesięcy i ułatwia ruch.","Krankengymnastik und Übungen":"Fizjoterapia i ćwiczenia","Sanfte Übungen im schmerzarmen Bereich erhalten die Beweglichkeit, am besten zusammen mit der Spritze.":"Delikatne ćwiczenia w zakresie mało bolesnym zachowują ruchomość, najlepiej razem z zastrzykiem.","Ibuprofen oder ähnliche Mittel helfen in der schmerzhaften Phase, vor allem zum Schlafen.":"Ibuprofen lub podobne leki pomagają w bolesnej fazie, zwłaszcza przy spaniu.","Gelenkaufdehnung mit Flüssigkeit":"Rozciąganie stawu płynem","Dabei wird die Kapsel mit Kochsalz und Kortison aufgedehnt; das kann kurzfristig mehr bringen als die Spritze allein.":"Torebka jest przy tym rozciągana solą fizjologiczną i kortyzonem; w krótkim czasie może dać więcej niż sam zastrzyk.","Narkose-Mobilisation oder OP":"Mobilizacja w znieczuleniu lub operacja","Für sehr hartnäckige Fälle; in einer großen Studie nicht besser als Krankengymnastik mit Spritze, aber mit mehr Risiken.":"Dla bardzo opornych przypadków; w dużym badaniu nie lepsza niż fizjoterapia z zastrzykiem, ale z większym ryzykiem.","Kräftiges Dehnen gegen den Schmerz":"Mocne rozciąganie wbrew bólowi","Gewaltsames Dehnen reizt die entzündete Kapsel und verlängert die schmerzhafte Phase eher.":"Gwałtowne rozciąganie drażni zapaloną torebkę i raczej wydłuża bolesną fazę.","Üben Sie täglich, aber nur bis zu einem leichten Ziehen – Schmerz ist hier kein Zeichen für Fortschritt.":"Proszę ćwiczyć codziennie, ale tylko do lekkiego ciągnięcia – ból nie jest tu oznaką postępu.","Ein Kissen unter dem Arm hilft vielen, nachts besser zu liegen.":"Poduszka pod ramieniem pomaga wielu osobom lepiej leżeć w nocy.","Bei Fieber, einer roten, heißen Schulter oder Schmerzen nach einem Sturz kommen Sie bitte sofort. Strahlt der Schmerz mit Atemnot oder Druck in der Brust in Schulter oder Arm, rufen Sie die 112.":"Przy gorączce, czerwonym, gorącym barku lub bólu po upadku proszę zgłosić się natychmiast. Jeśli ból promieniuje do barku lub ręki razem z dusznością albo uciskiem w klatce piersiowej, proszę dzwonić pod numer 112.","Epicondylitis humeri radialis":"Zapalenie nadkłykcia bocznego kości ramiennej","Der Schmerz sitzt außen am Ellenbogen, an einem kleinen Knochenvorsprung.":"Ból zlokalizowany jest po zewnętrznej stronie łokcia, przy małym wyrostku kostnym.","Er tritt auf, wenn Sie greifen, heben oder das Handgelenk anspannen – zum Beispiel beim Händeschütteln, Tragen einer Tasse oder Auswringen.":"Pojawia się przy chwytaniu, podnoszeniu lub napinaniu nadgarstka – na przykład przy podawaniu ręki, noszeniu filiżanki lub wyciskaniu ścierki.","Oft strahlt er in den Unterarm aus, und die Griffkraft lässt nach.":"Często promieniuje do przedramienia, a siła chwytu słabnie.","Mit Tennis hat es meist nichts zu tun: Die meisten Betroffenen spielen gar kein Tennis.":"Z tenisem zwykle nie ma to nic wspólnego: większość chorych w ogóle nie gra w tenisa.","Die leuchtenden Muskeln strecken Hand und Finger. Sie entspringen gemeinsam außen am Ellenbogen.":"Podświetlone mięśnie prostują dłoń i palce. Mają wspólny początek po zewnętrznej stronie łokcia.","Genau an diesem Ursprung ist die Sehne überlastet – dort tut es weh, wenn man drückt.":"Właśnie w tym miejscu początku ścięgno jest przeciążone – tam boli przy uciskaniu.","Die Sehne der Streckmuskeln wird durch viele gleichförmige Griff- und Drehbewegungen überlastet.":"Ścięgno mięśni prostowników jest przeciążane przez wiele jednostajnych ruchów chwytania i obracania.","Typisch sind Arbeit mit Werkzeug, viel Maus und Tastatur, Gartenarbeit oder Umzüge.":"Typowe są praca z narzędziami, dużo pracy z myszką i klawiaturą, prace w ogrodzie lub przeprowadzki.","Am häufigsten trifft es Menschen zwischen 35 und 55 Jahren.":"Najczęściej dotyka osób w wieku od 35 do 55 lat.","Die Sehne ist dabei weniger entzündet als vielmehr in ihrem Aufbau gestört. Sie braucht Zeit und dosierte Belastung, um sich zu erholen.":"Ścięgno jest przy tym nie tyle zapalnie zmienione, ile zaburzone w swojej budowie. Potrzebuje czasu i dawkowanego obciążenia, aby się zregenerować.","Bei etwa neun von zehn Menschen klingt der Tennisellenbogen innerhalb eines Jahres von selbst ab.":"U około dziewięciu na dziesięć osób łokieć tenisisty ustępuje samoistnie w ciągu roku.","Belastung anpassen":"Dostosowanie obciążenia","Auslösende Tätigkeiten reduzieren, ohne den Arm ganz zu schonen – das ist die Grundlage jeder Behandlung.":"Ograniczyć czynności wywołujące ból, bez całkowitego oszczędzania ręki – to podstawa każdego leczenia.",Kräftigungsübungen:"Ćwiczenia wzmacniające","Langsames Kräftigen der Streckmuskeln, zu Hause oder mit Krankengymnastik, kann die Erholung unterstützen.":"Powolne wzmacnianie mięśni prostowników, w domu lub z fizjoterapią, może wspierać powrót do zdrowia.",Schmerzgel:f,"Ein Gel mit Diclofenac oder Ibuprofen lindert den Schmerz für einige Wochen, mit wenig Nebenwirkungen.":"Żel z diklofenakiem lub ibuprofenem łagodzi ból na kilka tygodni, z niewielką liczbą działań niepożądanych.","Spange oder Bandage":"Opaska lub orteza","Eine Spange am Unterarm entlastet manche bei der Arbeit; gut untersucht ist das nicht.":"Opaska na przedramieniu odciąża niektóre osoby w pracy; nie jest to dobrze zbadane.","Stoßwellen, Eigenblut, PRP":"Fale uderzeniowe, krew własna, PRP","Diese meist selbst zu zahlenden Verfahren sind in Studien nicht klar besser als Abwarten.":"Te metody, zwykle płatne samodzielnie, w badaniach nie są wyraźnie lepsze niż czekanie.","Sie hilft nur wenige Wochen; nach einem Jahr geht es den Gespritzten im Schnitt schlechter, Rückfälle sind häufiger.":"Pomaga tylko przez kilka tygodni; po roku osoby z zastrzykami czują się średnio gorzej, a nawroty są częstsze.",Operation:S,"Nur in seltenen Ausnahmen; in einer Studie war die OP nicht besser als ein Scheineingriff.":"Tylko w rzadkich wyjątkach; w jednym badaniu operacja nie była lepsza niż zabieg pozorowany.","Greifen Sie Dinge mit der Handfläche nach oben, wie beim Tragen eines Tabletts – das schont die Sehne.":"Proszę chwytać przedmioty dłonią skierowaną ku górze, jak przy noszeniu tacy – to oszczędza ścięgno.","Machen Sie bei Arbeit am Computer oder mit Werkzeug regelmäßig kurze Pausen.":"Podczas pracy przy komputerze lub z narzędziami proszę regularnie robić krótkie przerwy.","Ist der Ellenbogen nach einem Sturz geschwollen oder lässt er sich nicht mehr strecken, kommen Sie bitte sofort. Bei Fieber, Rötung und Überwärmung ebenfalls.":"Jeśli łokieć po upadku jest opuchnięty lub nie daje się już wyprostować, proszę zgłosić się natychmiast. Tak samo przy gorączce, zaczerwienieniu i przegrzaniu.","Daumensattelgelenk-Arthrose":"Choroba zwyrodnieniowa stawu siodełkowatego kciuka","Der Schmerz sitzt an der Daumenwurzel, dort wo der Daumen in das Handgelenk übergeht.":"Ból zlokalizowany jest u nasady kciuka, tam gdzie kciuk przechodzi w nadgarstek.","Er tritt beim kräftigen Greifen auf: Glas aufdrehen, Schlüssel drehen, Wäsche auswringen, einen Knopf schließen.":"Pojawia się przy mocnym chwytaniu: odkręcaniu słoika, przekręcaniu klucza, wyżymaniu prania, zapinaniu guzika.","Mit der Zeit kann das Gelenk anschwellen und sich eine kleine Stufe an der Daumenwurzel bilden.":"Z czasem staw może spuchnąć, a u nasady kciuka może powstać niewielki uskok.","Die Kraft im Spitzgriff lässt nach, und Dinge fallen leichter aus der Hand.":"Siła chwytu szczypcowego słabnie, a przedmioty łatwiej wypadają z ręki.","Das leuchtende Knöchelchen in der Handwurzel bildet mit dem ersten Mittelhandknochen das Daumensattelgelenk.":"Podświetlona kostka w nadgarstku tworzy z pierwszą kością śródręcza staw siodełkowaty kciuka.","Es ist wie ein Reitsattel geformt und macht den Daumen so beweglich.":"Ma kształt siodła do jazdy konnej i dzięki temu kciuk jest ruchomy.","Bei der Arthrose wird der Knorpel dort dünn, und das Gelenk wird locker und schmerzhaft.":"W chorobie zwyrodnieniowej chrząstka w tym miejscu cienieje, a staw staje się luźny i bolesny.","Die Arthrose am Daumen ist sehr häufig, vor allem bei Frauen nach den Wechseljahren.":"Choroba zwyrodnieniowa kciuka jest bardzo częsta, zwłaszcza u kobiet po menopauzie.","Veranlagung spielt eine große Rolle – oft haben auch Mutter oder Großmutter krumme Finger.":"Duże znaczenie ma skłonność rodzinna – często także matka lub babcia mają krzywe palce.","Das Gelenk trägt bei jedem Griff viel Kraft. Lockere Bänder oder frühere Verletzungen beschleunigen den Verschleiß.":"Staw przenosi przy każdym chwycie dużą siłę. Poluzowane więzadła lub dawne urazy przyspieszają zużycie.","Wie stark es wehtut, passt oft nicht zum Röntgenbild.":"Nasilenie bólu często nie odpowiada obrazowi w zdjęciu rentgenowskim.","Die Beschwerden kommen und gehen in Schüben; bei vielen werden sie mit den Jahren ruhiger, auch wenn das Gelenk steifer wird.":"Dolegliwości występują okresowo; u wielu z czasem się uspokajają, nawet jeśli staw staje się sztywniejszy.",Daumenorthese:B,"Eine Schiene für die Daumenwurzel, vor allem nachts oder bei schwerer Arbeit, lindert bei vielen den Schmerz über Monate.":"Szyna na nasadę kciuka, zwłaszcza na noc lub przy ciężkiej pracy, łagodzi ból u wielu osób przez miesiące.","Übungen und Gelenkschutz":"Ćwiczenia i ochrona stawu","Übungen für die Daumenmuskeln und Hilfen im Alltag, oft mit Ergotherapie, verbessern Schmerz und Griff etwas.":"Ćwiczenia mięśni kciuka i pomoce w codziennym życiu, często w ramach terapii zajęciowej, nieco poprawiają ból i chwyt.","Ein Gel mit Diclofenac oder Ibuprofen ist an der Hand gut verträglich und hilft vielen in Schmerzphasen.":"Żel z diklofenakiem lub ibuprofenem jest dobrze tolerowany na dłoni i pomaga wielu osobom w okresach bólu.","Schmerzmittel als Tablette":"Leki przeciwbólowe w tabletkach","Ibuprofen oder ähnliche Mittel nur für kurze Zeit, wenn Gel und Schiene nicht reichen.":"Ibuprofen lub podobne leki tylko przez krótki czas, gdy żel i szyna nie wystarczają.","Bei starken Schmerzen trotz allem wird das kleine Vieleckbein entfernt; die meisten sind danach deutlich schmerzärmer.":"Przy silnym bólu mimo wszystko usuwa się małą kość czworoboczną większą; większość osób odczuwa potem wyraźnie mniej bólu.","Sie kann kurz lindern, war in Studien aber nicht klar besser als eine Scheinspritze.":"Może krótko złagodzić ból, ale w badaniach nie była wyraźnie lepsza niż zastrzyk pozorowany.",Hyaluronspritze:K,"Diese meist selbst zu zahlende Spritze bringt nach heutigem Wissen keinen echten Vorteil.":"Ten zastrzyk, zwykle płatny samodzielnie, według dzisiejszej wiedzy nie daje realnej korzyści.","Nutzen Sie Hilfen mit dickem Griff: Glasöffner, Schlüsselhilfe, dickere Stifte und Besteck.":"Proszę używać pomocy z grubym uchwytem: otwieracza do słoików, nakładki na klucz, grubszych długopisów i sztućców.","Wärme, etwa ein Handbad, lockert steife Finger am Morgen.":"Ciepło, na przykład kąpiel dłoni, rozluźnia sztywne palce rano.","Ist das Gelenk plötzlich rot, heiß und stark geschwollen, oder haben Sie nach einem Sturz starke Schmerzen am Daumen, kommen Sie bitte zeitnah.":"Jeśli staw nagle zrobi się czerwony, gorący i mocno opuchnięty lub po upadku pojawi się silny ból kciuka, proszę zgłosić się w trybie pilnym.",Karpaltunnelsyndrom:D,"eingeengter Mittelnerv":"zaciśnięty nerw pośrodkowy","Daumen, Zeige- und Mittelfinger kribbeln oder schlafen ein – typischerweise nachts oder früh am Morgen.":"Kciuk, palec wskazujący i środkowy mrowią lub drętwieją – typowo w nocy lub wcześnie rano.","Viele wachen davon auf und schütteln die Hand aus, bis es besser wird.":"Wiele osób budzi się z tego powodu i strząsa rękę, aż poczuje się lepiej.","Tagsüber tritt es beim Halten von Handy, Zeitung oder Lenkrad auf.":"W ciągu dnia pojawia się przy trzymaniu telefonu, gazety lub kierownicy.","Später können die Finger dauerhaft taub sein und das Greifen ungeschickt werden.":"Później palce mogą być stale zdrętwiałe, a chwytanie niezgrabne.","Der leuchtende Nerv versorgt Daumen, Zeige- und Mittelfinger mit Gefühl.":"Podświetlony nerw odpowiada za czucie kciuka, palca wskazującego i środkowego.","Am Handgelenk läuft er durch einen engen Kanal aus Handwurzelknochen, darüber spannt sich ein festes Band wie ein Dach.":"W nadgarstku biegnie przez wąski kanał utworzony przez kości nadgarstka, a nad nim jak dach rozpięte jest mocne więzadło.","Wird es in diesem Tunnel zu eng, drückt es auf den Nerv.":"Gdy w tym tunelu robi się zbyt ciasno, uciska on nerw.","Oft ist der Tunnel von Natur aus eng, und die Sehnen darin schwellen etwas an.":"Często tunel jest z natury wąski, a znajdujące się w nim ścięgna nieco puchną.","Häufiger betroffen sind Frauen, Schwangere und Menschen mit Diabetes, Übergewicht, Schilddrüsenunterfunktion oder Rheuma.":"Częściej chorują kobiety, kobiety w ciąży oraz osoby z cukrzycą, nadwagą, niedoczynnością tarczycy lub chorobami reumatycznymi.","Viel Arbeit mit gebeugtem Handgelenk oder vibrierenden Werkzeugen kann es verstärken.":"Dużo pracy ze zgiętym nadgarstkiem lub z narzędziami wibrującymi może nasilać dolegliwości.","Eine Messung der Nervenleitung beim Neurologen zeigt, wie stark der Nerv schon betroffen ist.":"Badanie przewodnictwa nerwowego u neurologa pokazuje, jak bardzo nerw jest już zajęty.","Leichte Beschwerden bessern sich oft mit einer Nachtschiene; ist der Nerv stark eingeengt, hilft die kleine Operation sehr zuverlässig.":"Lekkie dolegliwości często poprawiają się dzięki szynie na noc; jeśli nerw jest silnie uciśnięty, mała operacja pomaga bardzo skutecznie.","Schiene in der Nacht":"Szyna na noc","Sie hält das Handgelenk gerade und entlastet den Nerv; bei leichten Beschwerden ist das der erste Schritt.":"Utrzymuje nadgarstek prosto i odciąża nerw; przy lekkich dolegliwościach jest to pierwszy krok.","Eine Spritze in den Tunnel lindert die Beschwerden meist für einige Wochen bis Monate.":"Zastrzyk do tunelu łagodzi dolegliwości zwykle na kilka tygodni do kilku miesięcy.","Das Band über dem Tunnel wird durchtrennt – ein kurzer, ambulanter Eingriff, der auf Dauer am sichersten hilft.":"Więzadło nad tunelem zostaje przecięte – to krótki zabieg ambulatoryjny, który na dłuższą metę pomaga najpewniej.",Gleitübungen:"Ćwiczenia ślizgowe","Übungen für Sehnen und Nerv schaden nicht und tun manchen gut; der Nutzen ist kaum untersucht.":"Ćwiczenia ścięgien i nerwu nie szkodzą i niektórym służą; ich korzyść jest prawie niezbadana.","Ultraschall, Laser, Magnetfeld":"Ultradźwięki, laser, pole magnetyczne","Diese Geräte-Behandlungen haben keinen sicheren Nutzen gezeigt.":"Te zabiegi aparaturowe nie wykazały pewnej korzyści.","Tabletten und Vitamin B6":"Tabletki i witamina B6","Schmerzmittel, Entwässerungstabletten und Vitamine helfen dem eingeengten Nerv nicht.":"Leki przeciwbólowe, tabletki odwadniające i witaminy nie pomagają uciśniętemu nerwowi.","Vermeiden Sie es, das Handgelenk lange stark zu beugen – auch beim Schlafen nicht unter das Kissen legen.":"Proszę unikać długiego, mocnego zginania nadgarstka – podczas snu także nie wkładać ręki pod poduszkę.","Machen Sie bei Handarbeit, Computer oder Werkzeug regelmäßig Pausen und schütteln Sie die Hände locker aus.":"Podczas robótek ręcznych, pracy przy komputerze lub z narzędziami proszę robić regularne przerwy i luźno strząsać ręce.","Wird der Daumenballen schmaler, ist ein Finger dauerhaft taub oder fallen Ihnen Dinge aus der Hand, kommen Sie bitte bald – dann sollte der Nerv rasch entlastet werden.":"Jeśli kłąb kciuka się zmniejsza, palec jest stale zdrętwiały lub przedmioty wypadają z ręki, proszę zgłosić się wkrótce – wtedy nerw należy szybko odciążyć.","lumbal, Ischias":"lędźwiowy, rwa kulszowa","Der Schmerz zieht vom Rücken oder Gesäß in ein Bein, oft bis unter das Knie oder in den Fuß.":"Ból promieniuje z pleców lub pośladka do jednej nogi, często poniżej kolana lub do stopy.","Der Beinschmerz ist meist stärker als der Rückenschmerz und fühlt sich brennend oder elektrisierend an.":"Ból nogi jest zwykle silniejszy niż ból pleców i odczuwany jako palący lub jak porażenie prądem.","Kribbeln oder Taubheit an Bein oder Fuß sind häufig, manchmal auch eine leichte Schwäche.":"Mrowienie lub drętwienie nogi albo stopy są częste, czasem także lekkie osłabienie.","Husten, Niesen oder langes Sitzen können den Schmerz verstärken.":"Kaszel, kichanie lub długie siedzenie mogą nasilać ból.","Zwischen den Wirbeln liegen die Bandscheiben, wie Stoßdämpfer mit einem weichen Kern in der Mitte.":"Między kręgami leżą krążki międzykręgowe, jak amortyzatory z miękkim jądrem pośrodku.","Reißt der feste Ring außen ein, kann der leuchtende Kern nach hinten austreten.":"Gdy twardy pierścień zewnętrzny pęknie, podświetlone jądro może wydostać się do tyłu.","Dort drückt er auf eine Nervenwurzel und reizt sie – deshalb strahlt der Schmerz ins Bein aus.":"Tam uciska korzeń nerwowy i go drażni – dlatego ból promieniuje do nogi.","Bandscheiben verlieren mit den Jahren Wasser und Elastizität. Ein Vorfall ist meist Folge dieses natürlichen Alterns, nicht einer falschen Bewegung.":"Z wiekiem krążki tracą wodę i sprężystość. Przepuklina jest zwykle skutkiem tego naturalnego starzenia, a nie nieprawidłowego ruchu.","Am häufigsten trifft es Menschen zwischen 30 und 50 Jahren.":"Najczęściej dotyka osób w wieku od 30 do 50 lat.","Veranlagung, Rauchen, Übergewicht und schweres Heben erhöhen das Risiko.":"Skłonność rodzinna, palenie, nadwaga i dźwiganie ciężarów zwiększają ryzyko.","Ein MRT brauchen wir nur bei Lähmungen, Warnzeichen oder wenn eine Operation in Frage kommt. Vorwölbungen der Bandscheibe haben auch viele Menschen ohne Schmerzen.":"Rezonans magnetyczny jest nam potrzebny tylko przy porażeniach, objawach alarmowych lub gdy rozważana jest operacja. Wypuklenia krążka ma też wiele osób bez bólu.","Bei den meisten bessert sich der Schmerz innerhalb von 6 bis 12 Wochen deutlich – der Körper baut das ausgetretene Gewebe oft von selbst ab.":"U większości osób ból wyraźnie słabnie w ciągu 6 do 12 tygodni – organizm często sam wchłania wypchniętą tkankę.","In Bewegung bleiben":"Pozostanie w ruchu","Gehen und der normale Alltag, soweit es der Schmerz erlaubt, fördern die Heilung.":"Chodzenie i normalne codzienne czynności, na ile pozwala ból, sprzyjają gojeniu.","Ibuprofen oder ähnliche Mittel nehmen die Spitze des Schmerzes, damit Sie sich bewegen können; der Effekt ist eher klein.":"Ibuprofen lub podobne leki zdejmują szczyt bólu, aby można było się ruszać; efekt jest raczej niewielki.",Bewegungstherapie:P,"Krankengymnastik zeigt Ihnen Übungen und Haltungen, die das Bein entlasten.":"Fizjoterapia pokazuje ćwiczenia i pozycje, które odciążają nogę.","Spritze an die Nervenwurzel":"Zastrzyk przy korzeniu nerwowym","Bei starkem Beinschmerz kann eine gezielte Kortisonspritze den Schmerz für einige Wochen lindern.":"Przy silnym bólu nogi celowany zastrzyk z kortyzonu może złagodzić ból na kilka tygodni.","Sie nimmt den Beinschmerz schneller, nach einem Jahr geht es Operierten und Nicht-Operierten aber ähnlich gut; nötig ist sie bei Lähmungen.":"Szybciej usuwa ból nogi, ale po roku osoby operowane i nieoperowane czują się podobnie dobrze; jest konieczna przy porażeniach.","Opioide und Mittel gegen Nervenschmerz":"Opioidy i leki na ból neuropatyczny","Starke Schmerzmittel und Mittel wie Pregabalin helfen beim Ischias kaum, machen aber oft müde und schwindelig.":"Silne leki przeciwbólowe i leki takie jak pregabalina w rwie kulszowej pomagają niewiele, ale często powodują senność i zawroty głowy.",Bettruhe:M,"Liegen verzögert die Besserung und schwächt die Muskeln.":"Leżenie opóźnia poprawę i osłabia mięśnie.","Machen Sie das Aufstützen in Bauchlage nur, wenn der Beinschmerz dabei gleich bleibt oder sich in Richtung Rücken zurückzieht – zieht er weiter ins Bein, lassen Sie die Übung weg.":"Podpieranie się na przedramionach w leżeniu na brzuchu proszę wykonywać tylko wtedy, gdy ból nogi pozostaje przy tym taki sam lub cofa się w stronę pleców – jeśli ciągnie dalej w nogę, proszę zrezygnować z tego ćwiczenia.","Stehen Sie beim Sitzen alle 20 bis 30 Minuten kurz auf und gehen Sie ein paar Schritte.":"Podczas siedzenia proszę co 20 do 30 minut krótko wstać i przejść kilka kroków.","Taubheit im Schritt, am Gesäß oder an der Innenseite der Oberschenkel, Probleme beim Wasserlassen oder Stuhlgang: sofort in die Notaufnahme. Bitte ebenfalls sofort kommen bei zunehmender Lähmung des Beins oder Fußes, bei Fieber oder nach einem Unfall.":"Drętwienie w kroczu, w pośladkach lub po wewnętrznej stronie ud, problemy z oddawaniem moczu lub stolca: natychmiast na izbę przyjęć. Proszę też zgłosić się natychmiast przy narastającym porażeniu nogi lub stopy, przy gorączce lub po wypadku.","Enger Wirbelkanal":"Wąski kanał kręgowy","Nach einigen Minuten Gehen oder Stehen werden die Beine schwer, schmerzen, kribbeln oder werden taub.":"Po kilku minutach chodzenia lub stania nogi stają się ciężkie, bolą, mrowią lub drętwieją.","Hinsetzen oder Vornüberbeugen bringt rasch Erleichterung, etwa beim Abstützen auf einen Einkaufswagen.":"Usiądnięcie lub pochylenie się do przodu szybko przynosi ulgę, na przykład przy oparciu się o wózek sklepowy.","Radfahren und Bergaufgehen gehen oft erstaunlich gut, Bergabgehen schlechter.":"Jazda na rowerze i chodzenie pod górę często idą zaskakująco dobrze, schodzenie w dół gorzej.","Die Gehstrecke wird mit der Zeit kürzer.":"Dystans, jaki można przejść, z czasem się skraca.","Die leuchtenden Nervenfasern laufen im Wirbelkanal hinunter zu den Beinen.":"Podświetlone włókna nerwowe biegną w kanale kręgowym w dół do nóg.","Hinten begrenzen die gelben Bänder den Kanal; sie werden mit dem Alter dicker.":"Z tyłu kanał ograniczają żółte więzadła; z wiekiem stają się grubsze.","Zusammen mit Knochenanbauten und vorgewölbten Bandscheiben wird der Kanal eng – im Stehen enger als im Sitzen.":"Razem z wyroślami kostnymi i wypukłymi krążkami kanał się zwęża – w staniu bardziej niż w siedzeniu.","Die Einengung entsteht über viele Jahre durch Verschleiß der Wirbelsäule.":"Zwężenie powstaje przez wiele lat wskutek zużycia kręgosłupa.","Betroffen sind meist Menschen über 60 Jahre.":"Dotyka zwykle osób po 60. roku życia.","Beim aufrechten Stehen wird der Kanal enger, beim Vorbeugen und Sitzen weiter – deshalb hilft das Hinsetzen.":"W pozycji wyprostowanej kanał się zwęża, przy pochyleniu i w siedzeniu poszerza – dlatego pomaga usiąść.","Viele ältere Menschen haben im MRT einen engen Kanal ohne Beschwerden. Entscheidend ist, wie stark Sie eingeschränkt sind.":"Wiele starszych osób ma w rezonansie wąski kanał bez dolegliwości. Decydujące jest to, jak bardzo dolegliwości ograniczają codzienne życie.","Bei den meisten bleiben die Beschwerden über Jahre gleich oder bessern sich sogar; eine rasche Verschlechterung ist selten.":"U większości osób dolegliwości przez lata pozostają takie same lub nawet się poprawiają; szybkie pogorszenie jest rzadkie.","Übungen für Bauch, Rücken und Beweglichkeit sowie Radfahren halten Sie mobil; in Studien ähnlich wirksam wie eine OP.":"Ćwiczenia brzucha, pleców i ruchomości oraz jazda na rowerze utrzymują sprawność; w badaniach podobnie skuteczne jak operacja.","Ibuprofen oder ähnliche Mittel in schlechten Phasen; auf Dauer wegen Magen, Niere und Herz mit Vorsicht.":"Ibuprofen lub podobne leki w gorszych okresach; na dłuższą metę ostrożnie ze względu na żołądek, nerki i serce.","Operation zur Erweiterung":"Operacja poszerzająca","Bei stark verkürzter Gehstrecke kann die Erweiterung des Kanals helfen; ob sie auf Dauer mehr bringt als Bewegungstherapie, ist offen.":"Przy bardzo skróconym dystansie chodzenia poszerzenie kanału może pomóc; czy na dłuższą metę daje więcej niż terapia ruchem, nie jest pewne.","Zusätzliche Versteifung":"Dodatkowe usztywnienie","Ohne instabile Wirbelsäule bringt eine Versteifung zusätzlich zur Erweiterung meist keinen Vorteil.":"Bez niestabilnego kręgosłupa usztywnienie dodatkowo do poszerzenia zwykle nie daje korzyści.","Kortisonspritze in den Wirbelkanal":"Zastrzyk z kortyzonu do kanału kręgowego","Sie hilft bei engem Wirbelkanal in Studien nicht besser als eine Spritze ohne Kortison.":"W badaniach przy wąskim kanale kręgowym nie pomaga lepiej niż zastrzyk bez kortyzonu.","Mittel gegen Nervenschmerz":"Leki na ból neuropatyczny","Pregabalin oder Gabapentin verlängern die Gehstrecke nicht sicher und haben häufig Nebenwirkungen.":"Pregabalina lub gabapentyna nie wydłużają pewnie dystansu chodzenia i często mają działania niepożądane.","Radfahren, auch auf dem Heimtrainer, geht meist gut und hält die Beine fit.":"Jazda na rowerze, także stacjonarnym, zwykle idzie dobrze i utrzymuje nogi w formie.","Machen Sie beim Gehen rechtzeitig Pausen im Sitzen oder Vorbeugen; ein Rollator kann die Gehstrecke deutlich verlängern.":"Podczas chodzenia proszę robić przerwy odpowiednio wcześnie, w siedzeniu lub w pochyleniu; chodzik może wyraźnie wydłużyć dystans chodzenia.","Taubheit im Schritt oder am Gesäß, Probleme beim Wasserlassen oder Stuhlgang: sofort in die Notaufnahme. Bitte ebenfalls rasch kommen bei zunehmender Schwäche der Beine oder häufigen Stürzen.":"Drętwienie w kroczu lub w pośladkach, problemy z oddawaniem moczu lub stolca: natychmiast na izbę przyjęć. Proszę też szybko zgłosić się przy narastającym osłabieniu nóg lub częstych upadkach.",Nackenschmerzen:v,"Der Nacken ist schmerzhaft verspannt, der Kopf lässt sich schlechter drehen oder neigen.":"Kark jest boleśnie napięty, głowę trudniej obracać lub pochylać.","Der Schmerz kann in Hinterkopf, Schultern oder zwischen die Schulterblätter ziehen.":"Ból może promieniować do potylicy, barków lub między łopatki.","Oft kommt dazu ein Spannungskopfschmerz.":"Często dołącza się napięciowy ból głowy.","In den allermeisten Fällen steckt keine gefährliche Ursache dahinter.":"W zdecydowanej większości przypadków nie kryje się za tym żadna niebezpieczna przyczyna.","Die leuchtenden Muskeln halten und bewegen den Kopf – mehrere Kilo, den ganzen Tag lang.":"Podświetlone mięśnie podtrzymują i poruszają głowę – kilka kilogramów, przez cały dzień.","Bei Nackenschmerzen sind sie verspannt und druckempfindlich, oft auf beiden Seiten.":"Przy bólach karku są napięte i wrażliwe na ucisk, często po obu stronach.","Meist spielen Muskeln, Bänder und kleine Wirbelgelenke zusammen: verspannt, überlastet oder zu wenig bewegt.":"Zwykle współdziałają mięśnie, więzadła i małe stawy kręgosłupa: napięte, przeciążone lub zbyt mało ruszane.","Langes Arbeiten am Bildschirm oder Handy mit vorgeschobenem Kopf, Zugluft und eine ungünstige Schlafposition können es auslösen.":"Wywołać to może długa praca przy ekranie lub telefonie z wysuniętą głową, przeciąg i niekorzystna pozycja podczas snu.","Stress und Anspannung verstärken die Schmerzen und lassen sie länger anhalten.":"Stres i napięcie nasilają ból i przedłużają jego trwanie.","Verschleißzeichen im Röntgen haben auch viele Menschen ohne Beschwerden. Ein Bild brauchen wir nur bei Warnzeichen.":"Oznaki zużycia w rentgenie ma też wiele osób bez dolegliwości. Zdjęcie jest nam potrzebne tylko przy objawach alarmowych.","Die meisten Nackenschmerzen bessern sich innerhalb weniger Wochen; sie können wiederkommen, sind dann aber ebenso harmlos.":"Większość bólów karku poprawia się w ciągu kilku tygodni; mogą wrócić, ale są wtedy równie niegroźne.","Aktiv bleiben und üben":"Pozostać aktywnym i ćwiczyć","Den Kopf normal bewegen und regelmäßig Nacken und Schultern trainieren hilft am besten, auch gegen Rückfälle.":"Normalne ruszanie głową i regularne ćwiczenie karku i barków pomaga najlepiej, także przeciw nawrotom.",Wärme:"Ciepło","Wärmflasche, Kirschkernkissen oder eine warme Dusche lockern verspannte Muskeln.":"Termofor, woreczek z pestkami wiśni lub ciepły prysznic rozluźniają napięte mięśnie.","Manuelle Therapie":"Terapia manualna","Mobilisation durch Physiotherapie kann zusätzlich zu Übungen helfen, allein bringt sie wenig.":"Mobilizacja w ramach fizjoterapii może pomóc dodatkowo do ćwiczeń, sama daje niewiele.","Bei länger anhaltenden Schmerzen kann sie zusätzlich etwas lindern.":"Przy dłużej trwającym bólu może dodatkowo nieco złagodzić dolegliwości.","Ibuprofen oder ähnliche Mittel für wenige Tage, damit Sie in Bewegung bleiben können.":"Ibuprofen lub podobne leki przez kilka dni, aby można było pozostać w ruchu.","Massage allein":"Sam masaż","Tut gut, wirkt aber nur kurz; ohne eigene Übungen hält der Effekt nicht an.":"Sprawia przyjemność, ale działa tylko krótko; bez własnych ćwiczeń efekt nie utrzymuje się.","Halskrause und Muskelentspanner":"Kołnierz szyjny i leki rozluźniające mięśnie","Ruhigstellen schwächt die Muskeln, und Muskelentspanner machen müde und können abhängig machen.":"Unieruchomienie osłabia mięśnie, a leki rozluźniające mięśnie powodują senność i mogą uzależniać.","Stellen Sie den Bildschirm auf Augenhöhe und halten Sie das Handy höher statt den Kopf zu senken.":"Proszę ustawić ekran na wysokości oczu i trzymać telefon wyżej, zamiast opuszczać głowę.","Stehen Sie bei Schreibtischarbeit jede halbe Stunde kurz auf und kreisen Sie die Schultern.":"Przy pracy przy biurku proszę co pół godziny krótko wstać i zakreślić barkami koła.","Plötzlich stärkster Kopfschmerz, Lähmung oder Gefühlsstörung in Armen oder Beinen, unsicherer Gang, Fieber mit steifem Nacken oder Nackenschmerz nach einem Unfall: sofort in die Notaufnahme oder 112.":"Nagły, najsilniejszy ból głowy, porażenie lub zaburzenia czucia w rękach lub nogach, niepewny chód, gorączka ze sztywnym karkiem lub ból karku po wypadku: natychmiast na izbę przyjęć lub pod numer 112.",Fersenschmerz:W,"Plantarfasziitis, Fersensporn":"Zapalenie rozcięgna podeszwowego, ostroga piętowa","Unter der Fußsohle spannt sich eine kräftige Sehnenplatte von der Ferse bis zu den Zehen. Sie hält das Fußgewölbe.":"Pod podeszwą stopy rozpina się mocne rozcięgno od pięty do palców. Utrzymuje łuk stopy.","Wird sie überlastet, reizt sie sich dort, wo sie an der Ferse ansetzt.":"Gdy jest przeciążone, drażni się w miejscu, w którym przyczepia się do pięty.","Typisch ist ein stechender Schmerz bei den ersten Schritten am Morgen oder nach dem Sitzen. Nach ein paar Schritten wird es oft besser.":"Typowy jest kłujący ból przy pierwszych krokach rano lub po siedzeniu. Po kilku krokach często jest lepiej.","Nach langem Stehen oder Gehen kommt der Schmerz zurück.":"Po długim staniu lub chodzeniu ból wraca.","Sie sehen die Sehnenplatte, die vom Fersenbein fächerförmig zu den Zehen zieht.":"Widać rozcięgno, które rozchodzi się wachlarzowato od kości piętowej do palców.","Der Schmerz sitzt meist innen unten an der Ferse, genau an ihrem Ansatz.":"Ból zlokalizowany jest zwykle po wewnętrznej stronie u dołu pięty, dokładnie w miejscu przyczepu.","Meist ist es zu viel Belastung auf einmal: viel Stehen, viel Gehen, mehr Sport, neue oder flache Schuhe.":"Zwykle chodzi o zbyt duże obciążenie naraz: dużo stania, dużo chodzenia, więcej sportu, nowe lub płaskie buty.","Eine verkürzte Wade und Übergewicht erhöhen den Zug an der Sehnenplatte.":"Skrócona łydka i nadwaga zwiększają napięcie rozcięgna.","Der ständige Zug kann am Fersenbein einen kleinen Knochensporn wachsen lassen. Er ist Folge, nicht Ursache – viele Menschen haben einen Sporn ohne jeden Schmerz.":"Stałe napięcie może spowodować wyrośnięcie na kości piętowej małej ostrogi kostnej. Jest skutkiem, a nie przyczyną – wiele osób ma ostrogę bez żadnego bólu.","Ein Röntgenbild brauchen wir deshalb meist nicht. Es ändert an der Behandlung nichts.":"Zdjęcie rentgenowskie jest więc zwykle niepotrzebne. Nie zmienia leczenia.","Fast immer heilt es ohne Operation aus – oft dauert es aber 6 bis 12 Monate. Geduld und tägliches Dehnen lohnen sich.":"Prawie zawsze goi się bez operacji – często trwa to jednak od 6 do 12 miesięcy. Cierpliwość i codzienne rozciąganie się opłacają.",Dehnübungen:"Ćwiczenia rozciągające","Tägliches Dehnen von Fußsohle und Wade ist die wichtigste Behandlung und lindert den Schmerz auf Dauer.":"Codzienne rozciąganie podeszwy i łydki to najważniejsza metoda leczenia, która trwale łagodzi ból.",Stoßwellen:"Fale uderzeniowe","Bei Beschwerden über mehr als 6 Monate helfen Stoßwellen vielen; dann zahlt sie die Kasse beim Orthopäden.":"Przy dolegliwościach trwających ponad 6 miesięcy fale uderzeniowe pomagają wielu osobom; wtedy kasa chorych (Krankenkasse) pokrywa je u ortopedy.","Einlagen und Fersenkissen":"Wkładki i podkładki pod piętę","Weiche Fersenkissen oder einfache Einlagen können entlasten; teure Maßeinlagen sind nicht besser als fertige.":"Miękkie podkładki pod piętę lub proste wkładki mogą odciążyć; drogie wkładki na miarę nie są lepsze od gotowych.","Tape und Nachtschiene":"Taping i szyna na noc","Ein Tape stützt für einige Tage, eine Nachtschiene hält die Sehnenplatte nachts gedehnt und mildert den Morgenschmerz.":"Taping wspiera przez kilka dni, szyna na noc utrzymuje rozcięgno w nocy rozciągnięte i łagodzi poranny ból.","Lindert für einige Wochen, kann aber das Fettpolster der Ferse schwinden lassen oder die Sehnenplatte reißen lassen.":"Łagodzi na kilka tygodni, ale może spowodować zanik poduszki tłuszczowej pięty lub zerwanie rozcięgna.","Ibuprofen oder eine Schmerzsalbe dürfen für kurze Zeit helfen, heilen aber nichts.":"Ibuprofen lub maść przeciwbólowa mogą krótko pomóc, ale niczego nie leczą.","Gehen Sie nicht barfuß auf hartem Boden. Tragen Sie Schuhe mit gut gedämpfter Ferse – auch zu Hause.":"Proszę nie chodzić boso po twardej podłodze. Proszę nosić buty z dobrze amortyzowaną piętą – także w domu.","Dehnen Sie die Fußsohle schon im Bett, bevor Sie morgens aufstehen.":"Proszę rozciągać podeszwę już w łóżku, zanim rano wstanie się na nogi.","Plötzlicher Knall oder Riss unter der Fußsohle, starke Schwellung oder Bluterguss, Taubheit oder Kribbeln im Fuß, Schmerz auch nachts in Ruhe: bitte bald wiederkommen.":"Nagły trzask lub zerwanie pod podeszwą, silny obrzęk lub siniak, drętwienie lub mrowienie stopy, ból także w nocy w spoczynku: proszę zgłosić się ponownie wkrótce.",Achillessehnenschmerz:G,"Achillodynie, Achillessehnen-Tendinopathie":"Achillodynia, tendinopatia ścięgna Achillesa","Die Achillessehne verbindet die Wadenmuskeln mit der Ferse. Sie ist die stärkste Sehne des Körpers.":"Ścięgno Achillesa łączy mięśnie łydki z piętą. Jest to najsilniejsze ścięgno w ciele.","Bei Überlastung wird sie schmerzhaft, oft verdickt und druckempfindlich.":"Przy przeciążeniu staje się bolesne, często pogrubiałe i wrażliwe na ucisk.","Typisch ist eine Steifigkeit am Morgen und ein Schmerz zu Beginn der Belastung, der sich beim Warmlaufen bessert und danach wiederkommt.":"Typowa jest sztywność rano i ból na początku obciążenia, który zmniejsza się podczas rozgrzewki, a potem wraca.","Sie sehen die Sehne hinten zwischen Wadenmuskel und Fersenbein.":"Widać ścięgno z tyłu, między mięśniem łydki a kością piętową.","Meist schmerzt sie zwei bis sechs Zentimeter über der Ferse, seltener direkt am Ansatz am Knochen.":"Najczęściej boli dwa do sześciu centymetrów nad piętą, rzadziej bezpośrednio w miejscu przyczepu do kości.","Die Sehne bekommt mehr Last, als sie gewohnt ist – zum Beispiel durch mehr Laufen, Bergauf-Gehen oder Springen.":"Ścięgno otrzymuje większe obciążenie, niż jest przyzwyczajone – na przykład przez więcej biegania, chodzenia pod górę lub skakania.","Das Gewebe der Sehne baut sich dabei um und wird empfindlich. Eine echte Entzündung ist es meist nicht.":"Tkanka ścięgna ulega wtedy przebudowie i staje się wrażliwa. Zwykle nie jest to prawdziwy stan zapalny.","Das Risiko steigt mit dem Alter, mit Übergewicht, Diabetes, hohen Blutfetten und bei manchen Antibiotika (Chinolonen).":"Ryzyko rośnie z wiekiem, przy nadwadze, cukrzycy, wysokim poziomie tłuszczów we krwi i przy niektórych antybiotykach (chinolonach).","Mit regelmäßigem Krafttraining werden die meisten in 3 bis 6 Monaten deutlich besser. Die Sehne braucht Zeit, aber sie lässt sich trainieren.":"Przy regularnym treningu siłowym większość osób czuje się wyraźnie lepiej po 3 do 6 miesiącach. Ścięgno potrzebuje czasu, ale można je trenować.","Krafttraining für die Wade":"Trening siłowy łydki","Langsames Fersenheben, das sich Woche für Woche steigert, kräftigt die Sehne und ist die wichtigste Behandlung.":"Powolne unoszenie pięt, zwiększane z tygodnia na tydzień, wzmacnia ścięgno i jest najważniejszą metodą leczenia.","Laufen und Springen vorübergehend reduzieren, aber nicht ganz ruhigstellen – leichter Schmerz bis 3 von 10 ist erlaubt.":"Ograniczyć na pewien czas bieganie i skakanie, ale nie unieruchamiać całkowicie – lekki ból do 3 w skali do 10 jest dozwolony.",Fersenkeil:A,"Eine kleine Erhöhung im Schuh entlastet die Sehne vorübergehend, besonders wenn es direkt an der Ferse schmerzt.":"Mała wkładka podnosząca piętę w bucie czasowo odciąża ścięgno, zwłaszcza gdy boli bezpośrednio przy pięcie.","Können zusätzlich zum Training helfen, wenn es nach Monaten nicht besser wird; meist müssen Sie sie selbst bezahlen.":"Mogą pomóc dodatkowo do treningu, jeśli po miesiącach nie ma poprawy; zwykle trzeba za nie zapłacić samodzielnie.","Eigenblut-Spritze (PRP)":"Zastrzyk z krwi własnej (PRP)","Hat in guten Studien nicht besser gewirkt als eine Scheinspritze und kostet Geld.":"W dobrych badaniach nie działał lepiej niż zastrzyk pozorowany i kosztuje.","Wird an der Achillessehne nicht gegeben, weil sie die Sehne schwächt und reißen lassen kann.":"Nie podaje się go w ścięgno Achillesa, ponieważ osłabia ścięgno i może doprowadzić do jego zerwania.","Halten Sie das Training durch, auch wenn es leicht zieht. Wichtig ist, dass der Schmerz am nächsten Morgen nicht stärker ist.":"Proszę wytrwać w treningu, nawet jeśli lekko ciągnie. Ważne, aby ból następnego ranka nie był silniejszy.","Steigern Sie Laufen oder Sport später nur langsam, etwa um ein Zehntel pro Woche.":"Bieganie lub sport proszę później zwiększać tylko powoli, mniej więcej o jedną dziesiątą tygodniowo.","Ein plötzlicher Knall oder Schlag in der Ferse, danach Gehen nur noch mühsam und Zehenspitzenstand auf dem Bein unmöglich: Das kann ein Riss sein – bitte sofort kommen.":"Nagły trzask lub uderzenie w pięcie, potem chodzenie tylko z trudem i niemożność stania na palcach tej nogi: może to być zerwanie – proszę zgłosić się natychmiast.",Ballenzeh:C,"Die große Zehe weicht zu den anderen Zehen hin ab. Dafür tritt das Grundgelenk innen als Ballen hervor.":"Duży palec odchyla się w stronę pozostałych palców. Przy tym staw podstawy wystaje po stronie wewnętrznej jako haluks.","Am Ballen drückt der Schuh. Die Haut kann sich röten und ein Schleimbeutel kann sich entzünden.":"Na haluksie uciska but. Skóra może się zaczerwienić, a kaletka maziowa może ulec zapaleniu.","Manchmal schiebt sich die große Zehe unter die zweite. Auch Schmerzen unter dem Vorfuß sind häufig.":"Czasem duży palec wsuwa się pod drugi. Częsty jest też ból pod przodostopiem.","Sie sehen die fünf Mittelfußknochen von oben.":"Widać pięć kości śródstopia z góry.","Beim Ballenzeh weicht der erste Mittelfußknochen nach innen ab, die Großzehe kippt nach außen. Dort, am Kopf des ersten Knochens, entsteht der Ballen.":"W palucha koślawym pierwsza kość śródstopia odchyla się do wewnątrz, a paluch przechyla się na zewnątrz. Tam, na główce pierwszej kości, powstaje haluks.","Die Veranlagung spielt die größte Rolle. Oft haben schon Mutter oder Großmutter einen Ballenzeh.":"Największe znaczenie ma skłonność rodzinna. Często matka lub babcia mają już paluch koślawy.","Frauen sind viel häufiger betroffen. Enge, spitze Schuhe und hohe Absätze verstärken die Fehlstellung.":"Kobiety chorują znacznie częściej. Wąskie, szpiczaste buty i wysokie obcasy nasilają wadę.","Ein Spreizfuß, bei dem der Vorfuß breiter wird, begünstigt den Schiefstand.":"Płaskostopie poprzeczne, przy którym przodostopie się poszerza, sprzyja skrzywieniu.","Die Fehlstellung bildet sich nicht von selbst zurück. Viele Menschen kommen mit passenden Schuhen aber gut zurecht und brauchen nie eine Operation.":"Wada nie cofa się samoistnie. Wiele osób dobrze sobie jednak radzi w odpowiednim obuwiu i nigdy nie potrzebuje operacji.","Weite, weiche Schuhe":"Szerokie, miękkie buty","Schuhe mit breitem Vorderteil und flachem Absatz nehmen den Druck vom Ballen und lindern den Schmerz.":"Buty z szerokim przodem i płaskim obcasem zdejmują nacisk z haluksa i łagodzą ból.","Polster und Zehenspreizer":"Podkładki i rozpieracze palców","Ein Ballenpolster oder Zehenspreizer aus Silikon schützt die Haut und kann den Schmerz mildern.":"Podkładka na haluks lub silikonowy rozpieracz palców chroni skórę i może złagodzić ból.",Einlagen:N,"Bei Schmerzen unter dem Vorfuß kann eine Einlage mit Pelotte entlasten; den Schiefstand korrigiert sie nicht.":"Przy bólu pod przodostopiem może odciążyć wkładka z pelotą; skrzywienia nie koryguje.",Fußübungen:"Ćwiczenia stóp","Übungen kräftigen die kleinen Fußmuskeln; ob sie den Schiefstand aufhalten, ist kaum untersucht.":"Ćwiczenia wzmacniają małe mięśnie stopy; czy powstrzymują skrzywienie, jest prawie niezbadane.",Nachtschiene:T,"Zieht die Zehe nachts gerade, doch tagsüber kehrt die Fehlstellung zurück; ein dauerhafter Nutzen ist nicht belegt.":"Prostuje palec w nocy, ale w ciągu dnia wada wraca; trwała korzyść nie została wykazana.","Wenn trotz passender Schuhe der Schmerz bleibt, richtet eine Operation den Knochen gerade; danach braucht der Fuß etwa 6 Wochen Schonung.":"Jeśli mimo odpowiednich butów ból pozostaje, operacja prostuje kość; potem stopa potrzebuje około 6 tygodni oszczędzania.","Kaufen Sie Schuhe am Nachmittag, wenn der Fuß etwas dicker ist, und achten Sie auf Platz für die Zehen.":"Proszę kupować buty po południu, gdy stopa jest nieco grubsza, i zwracać uwagę, aby było miejsce dla palców.","Gehen Sie zu Hause öfter barfuß – das trainiert die Fußmuskeln.":"W domu proszę częściej chodzić boso – to trenuje mięśnie stóp.","Ein plötzlich heißes, rotes, stark schmerzendes Großzehengelenk kann ein Gichtanfall oder eine Entzündung sein: bitte bald kommen. Bei Diabetes jede offene Stelle am Ballen sofort zeigen.":"Nagle gorący, czerwony, bardzo bolesny staw dużego palca może oznaczać napad dny moczanowej lub zapalenie: proszę zgłosić się wkrótce. Przy cukrzycy każdą otwartą ranę na haluksie proszę pokazać natychmiast.",Gonarthrose:Z,"Oberschenkel und Schienbein sind im Knie mit glattem Knorpel überzogen. Er federt ab und lässt das Gelenk gleiten.":"Kość udowa i piszczel są w kolanie pokryte gładką chrząstką. Amortyzuje ona i pozwala stawowi się ślizgać.","Bei Arthrose wird dieser Knorpel dünner und rauer. Der Knochen darunter reagiert, das Gelenk wird enger.":"W chorobie zwyrodnieniowej ta chrząstka staje się cieńsza i szorstka. Kość pod nią reaguje, staw się zwęża.","Typisch sind Schmerzen beim Loslaufen, beim Treppensteigen und nach längerem Gehen. Das Knie ist morgens steif und kann anschwellen.":"Typowy jest ból przy rozpoczynaniu chodzenia, przy wchodzeniu po schodach i po dłuższym chodzeniu. Kolano jest rano sztywne i może puchnąć.","Sie sehen das Knie von vorn. Der Knorpelbelag liegt hell auf dem Ende des Oberschenkels und auf dem Schienbein, dazwischen die Menisken als Puffer.":"Widać kolano od przodu. Warstwa chrząstki leży jasno na końcu kości udowej i na piszczeli, a między nimi łąkotki jako bufor.","Meist verschleißt zuerst die Innenseite, wo der Innenmeniskus liegt. Dort sitzt dann auch der Schmerz.":"Zwykle najpierw zużywa się strona wewnętrzna, gdzie leży łąkotka przyśrodkowa. Tam też jest ból.","Arthrose entwickelt sich über viele Jahre. Alter und Veranlagung spielen die größte Rolle.":"Choroba zwyrodnieniowa rozwija się przez wiele lat. Największe znaczenie mają wiek i skłonność rodzinna.","Übergewicht belastet das Knie bei jedem Schritt mehrfach und fördert die Reizung im Gelenk.":"Nadwaga obciąża kolano wielokrotnie przy każdym kroku i nasila podrażnienie w stawie.","Auch alte Verletzungen an Meniskus oder Kreuzband und O-Beine erhöhen das Risiko.":"Także dawne urazy łąkotki lub więzadła krzyżowego oraz kolana szpotawe zwiększają ryzyko.","Das Röntgenbild sagt wenig darüber, wie stark die Beschwerden sind.":"Zdjęcie rentgenowskie niewiele mówi o tym, jak silne są dolegliwości.","Arthrose verläuft in Schüben, und viele Menschen haben über Jahre gute Phasen. Wer sich regelmäßig bewegt, hat weniger Schmerzen und bleibt beweglich.":"Choroba zwyrodnieniowa przebiega rzutami, a wiele osób ma przez lata dobre okresy. Kto regularnie się rusza, ma mniej bólu i zachowuje sprawność.","Bewegung und Krafttraining":"Ruch i trening siłowy","Gezielte Übungen für die Oberschenkelmuskeln lindern den Schmerz so gut wie Tabletten – anfangs kann es etwas mehr wehtun, das ist erlaubt.":"Celowane ćwiczenia mięśni uda łagodzą ból równie dobrze jak tabletki – na początku może boleć nieco bardziej, jest to dozwolone.","Abnehmen bei Übergewicht":"Odchudzanie przy nadwadze","Jedes Kilo weniger entlastet das Knie spürbar und bremst den Verschleiß.":"Każdy kilogram mniej wyraźnie odciąża kolano i spowalnia zużycie.","Am besten als Salbe mit Diclofenac oder Ibuprofen; Tabletten nur kurz in schlechten Phasen, denn sie belasten Magen, Niere und Herz.":"Najlepiej jako maść z diklofenakiem lub ibuprofenem; tabletki tylko krótko w gorszych okresach, ponieważ obciążają żołądek, nerki i serce.","Beruhigt ein gereiztes, geschwollenes Knie für 2 bis 10 Wochen; nicht zu oft wiederholen.":"Uspokaja podrażnione, spuchnięte kolano na 2 do 10 tygodni; nie powtarzać zbyt często.","Nützt in Studien kaum mehr als eine Scheinspritze und muss selbst bezahlt werden.":"W badaniach przynosi niewiele więcej niż zastrzyk pozorowany i trzeba za niego zapłacić samodzielnie.",Gelenkspiegelung:F,"Ein Ausspülen oder Glätten des Knorpels hilft bei Arthrose nicht besser als Übungen.":"Płukanie lub wygładzanie chrząstki przy chorobie zwyrodnieniowej nie pomaga lepiej niż ćwiczenia.","Künstliches Kniegelenk":"Sztuczny staw kolanowy","Wenn Schmerz und Einschränkung trotz allem nicht mehr erträglich sind, bringt ein neues Gelenk den meisten deutlich weniger Schmerz.":"Gdy ból i ograniczenie ruchu mimo wszystko stają się nie do zniesienia, nowy staw przynosi większości osób wyraźnie mniej bólu.","Bewegen Sie das Knie viel, aber ohne Stöße: Radfahren, Schwimmen, Gehen auf ebenem Weg.":"Proszę dużo ruszać kolanem, ale bez wstrząsów: jazda na rowerze, pływanie, chodzenie po równej drodze.","Bei einem dicken, warmen Knie hilft Kühlen, bei einem steifen Knie Wärme.":"Przy opuchniętym, ciepłym kolanie pomaga chłodzenie, przy sztywnym kolanie ciepło.","Ein plötzlich heißes, rotes, stark geschwollenes Knie mit Fieber – besonders nach einer Spritze – ist ein Notfall: bitte sofort kommen. Auch eine pralle, schmerzhafte Wade gehört sofort untersucht.":"Nagle gorące, czerwone, mocno opuchnięte kolano z gorączką – zwłaszcza po zastrzyku – to nagły przypadek: proszę zgłosić się natychmiast. Także napięta, bolesna łydka wymaga natychmiastowego zbadania.",Coxarthrose:H,"Das Hüftgelenk ist ein Kugelgelenk: Der runde Hüftkopf dreht sich in der Pfanne des Beckens. Beide sind mit glattem Knorpel überzogen.":"Staw biodrowy jest stawem kulistym: okrągła głowa kości udowej obraca się w panewce miednicy. Oba elementy pokryte są gładką chrząstką.","Bei Arthrose wird der Knorpel dünner, das Gelenk wird enger und steifer.":"W chorobie zwyrodnieniowej chrząstka staje się cieńsza, staw się zwęża i sztywnieje.","Der Schmerz sitzt meist in der Leiste und kann ins Knie ziehen. Typisch sind Anlaufschmerz und Mühe beim Schuhe- oder Strümpfeanziehen.":"Ból zlokalizowany jest zwykle w pachwinie i może promieniować do kolana. Typowy jest ból na początku chodzenia i trudność w zakładaniu butów lub skarpet.","Sie sehen den Oberschenkelknochen mit seinem kugeligen Kopf, der in der Pfanne des Beckens sitzt.":"Widać kość udową z jej kulistą głową, która tkwi w panewce miednicy.","Zwischen Kopf und Pfanne liegt der Knorpel, der bei Arthrose schwindet. Gespürt wird das vor allem in der Leiste.":"Między głową a panewką leży chrząstka, która w chorobie zwyrodnieniowej zanika. Odczuwa się to głównie w pachwinie.","Passen Hüftkopf und Pfanne von Geburt an nicht genau zueinander, verschleißt der Knorpel früher.":"Jeśli głowa kości udowej i panewka od urodzenia nie pasują do siebie dokładnie, chrząstka zużywa się wcześniej.","Auch frühere Verletzungen, Übergewicht und schwere körperliche Arbeit begünstigen sie.":"Sprzyjają jej także dawne urazy, nadwaga i ciężka praca fizyczna.","Viele Menschen kommen mit Bewegung und Übungen über Jahre gut zurecht. Wird es zu schlimm, hilft ein künstliches Hüftgelenk sehr zuverlässig.":"Wiele osób dobrze radzi sobie przez lata dzięki ruchowi i ćwiczeniom. Gdy jest zbyt źle, sztuczny staw biodrowy pomaga bardzo skutecznie.","Übungen für Gesäß und Hüfte lindern den Schmerz und halten das Gelenk beweglich – das ist die wichtigste Behandlung.":"Ćwiczenia pośladków i biodra łagodzą ból i utrzymują ruchomość stawu – to najważniejsza metoda leczenia.",Schmerztabletten:E,"Ibuprofen oder Naproxen helfen in schlechten Phasen, aber nur kurz, weil sie Magen, Niere und Herz belasten.":"Ibuprofen lub naproksen pomagają w gorszych okresach, ale tylko krótko, ponieważ obciążają żołądek, nerki i serce.","Weniger Gewicht entlastet die Hüfte; der Nutzen ist hier etwas kleiner als am Knie.":"Mniejsza masa ciała odciąża biodro; korzyść jest tu nieco mniejsza niż w kolanie.","In der Hand auf der gesunden Seite entlastet er die kranke Hüfte spürbar.":"Trzymana w ręce po stronie zdrowej, wyraźnie odciąża chore biodro.","Kann die Hüfte für einige Wochen beruhigen; sie wird unter Ultraschall- oder Röntgensicht gesetzt.":"Może uspokoić biodro na kilka tygodni; podaje się go pod kontrolą USG lub rentgena.","Hat an der Hüfte keinen sicheren Nutzen gezeigt und muss selbst bezahlt werden.":"W biodrze nie wykazał pewnej korzyści i trzeba za niego zapłacić samodzielnie.","Künstliches Hüftgelenk":"Sztuczny staw biodrowy","Bei starken Schmerzen trotz allem gehört es zu den erfolgreichsten Operationen überhaupt; die meisten gehen danach fast schmerzfrei.":"Przy silnym bólu mimo wszystko należy do najbardziej udanych operacji w ogóle; większość osób jest potem prawie bez bólu.","Radfahren und Schwimmen schonen die Hüfte und halten sie beweglich.":"Jazda na rowerze i pływanie oszczędzają biodro i utrzymują jego ruchomość.","Ein erhöhter Sitz und ein Strumpfanzieher erleichtern den Alltag, wenn das Beugen schwerfällt.":"Podwyższone siedzisko i pomoc do zakładania skarpet ułatwiają codzienne życie, gdy zginanie sprawia trudność.","Plötzliche starke Hüftschmerzen nach einem Sturz, wenn das Bein nicht mehr belastet werden kann: sofort kommen. Ebenso bei Fieber und heißer, schmerzhafter Hüfte oder bei neuen Schmerzen nachts in Ruhe.":"Nagły silny ból biodra po upadku, gdy nie można już obciążać nogi: proszę zgłosić się natychmiast. Tak samo przy gorączce i gorącym, bolesnym biodrze lub przy nowym bólu w nocy w spoczynku.","Schmerz am Kreuz-Darmbein-Gelenk":"Ból stawu krzyżowo-biodrowego","ISG-Syndrom, ISG-Blockade":"Zespół stawu krzyżowo-biodrowego, blokada stawu krzyżowo-biodrowego","Das Kreuz-Darmbein-Gelenk verbindet das Kreuzbein mit der Beckenschaufel – rechts und links je eines.":"Staw krzyżowo-biodrowy łączy kość krzyżową z talerzem kości biodrowej – po jednym po prawej i lewej stronie."};export{G as Achillessehnenschmerz,j as Akupunktur,o as Ballen,C as Ballenzeh,e as Bandscheibenvorfall,M as Bettruhe,P as Bewegungstherapie,H as Coxarthrose,s as Darmbein,B as Daumenorthese,N as Einlagen,k as Engpass,A as Fersenkeil,W as Fersenschmerz,l as Fersensporn,F as Gelenkspiegelung,Z as Gonarthrose,t as Halswirbel,K as Hyaluronspritze,d as Karpaltunnel,D as Karpaltunnelsyndrom,a as Kniearthrose,b as Knochenvorsprung,n as Knochenzacken,y as Kortisonspritze,r as Meniskus,T as Nachtschiene,v as Nackenschmerzen,S as Operation,z as Plantarfasziitis,u as Rhizarthrose,h as Sattelgelenk,f as Schmerzgel,E as Schmerztabletten,w as Schulterdach,i as Schultersteife,c as Sehnen,m as Spinalkanalstenose,g as Streckmuskeln,p as Tennisellenbogen,R as default};
